# (HIMS-PAT-004) may move a row to the kept patient, so patient_id alone may change.
HISTORY_GUARD = """
CREATE OR REPLACE FUNCTION patient_history_guard() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION '% rows are never deleted', TG_TABLE_NAME;
    END IF;
    IF (to_jsonb(NEW) - 'patient_id') IS DISTINCT FROM (to_jsonb(OLD) - 'patient_id') THEN
        RAISE EXCEPTION '% rows never change; record a new one', TG_TABLE_NAME;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER patient_aliases_history
    BEFORE UPDATE OR DELETE ON patient_aliases
    FOR EACH ROW EXECUTE FUNCTION patient_history_guard();
CREATE TRIGGER patient_consents_history
    BEFORE UPDATE OR DELETE ON patient_consents
    FOR EACH ROW EXECUTE FUNCTION patient_history_guard();
"""

